{
  "qa": [
    {
      "question": "在十字路口，A车与B车发生碰撞导致B车司机及路人乙死亡，A车是否负主要责任？",
      "answer": "A车因避让行为导致B车冲出撞死路人乙，且A车未闯红灯，故负主要责任。"
    },
    {
      "question": "路人甲在事故中是否存在违规行为？",
      "answer": "路人甲存在探头闯红灯的违规行为，导致事故后果。"
    },
    {
      "question": "A车在事故中是否属于正常行驶且未闯红灯？",
      "answer": "A车在南北方向直行时处于绿灯状态，未闯红灯，属于正常行驶。"
    }
  ]
}
